// (flutter_features_config.dart: the env override is read per invocation),
// the migration then skips cleanly ("The Swift Package Manager feature is
// off. Skipping..."), and every macOS plugin is already pinned in
// macos/Podfile.lock. The Podfile platform (:osx, '14.0') — not a silent
// tool bump — becomes the authority for the effective pod floors.
//
// This suite pins the REG gate script that turns that decision into a loud,
// build-time invariant (scripts/assert_macos_min_platform.sh), invoked in
// the Build macOS release step AFTER `flutter build macos --config-only`
// (which drives the real tool's SPM/pods config pass without compiling):
//
//   AC1  a clean pods-lane tree passes (exit 0);
//   AC2  any SwiftPM re-entry fails loud with the gh-180 remediation —
//        either the FlutterGeneratedPluginSwiftPackage marker in the
//        pbxproj (env pin lost / tool default flipped) or a plugin that
//        regained its Package.swift (SwiftPM opt-in signal);
//   AC3  the literal gh-180 violation shape (generated package floor
//        12.0 + plugin product floor 14.0) fails with the specific floor
//        message, not just the generic lane message;
//   AC4  the floor scan covers EVERY package manifest under the generated
//        tree — a violation in a later manifest is caught too (a
//        single-item scan can pass while multi-item logic is broken);
//   AC5  app-floor drift fails: any MACOSX_DEPLOYMENT_TARGET ≠ 14.0 in
//        the pbxproj, or a Podfile platform ≠ 14.0;
//   AC6  a missing pbxproj/Podfile fails gracefully (no false green).
import 'dart:io';

import 'package:test/test.dart';

const scriptPath = 'scripts/assert_macos_min_platform.sh';
const appMin = '14.0';

/// A minimal Runner.xcodeproj shape the gate accepts: exactly the Runner
/// target's three configs (Debug/Release/Profile) carry the floor.
String pbxprojWith(String deploymentTargetLine) => '''
\t\t33CC10F9 /* Debug */ = {
\t\t\tisa = XCBuildConfiguration;
\t\t\tbuildSettings = {
\t\t\t\tMACOSX_DEPLOYMENT_TARGET = $deploymentTargetLine;
\t\t\t};
\t\t\tname = Debug;
\t\t};
\t\t33CC10FA /* Release */ = {
\t\t\tisa = XCBuildConfiguration;
\t\t\tbuildSettings = {
\t\t\t\tMACOSX_DEPLOYMENT_TARGET = $deploymentTargetLine;
\t\t\t};
\t\t\tname = Release;
\t\t};
\t\t338D0CE9 /* Profile */ = {
\t\t\tisa = XCBuildConfiguration;
\t\t\tbuildSettings = {
\t\t\t\tMACOSX_DEPLOYMENT_TARGET = $deploymentTargetLine;
\t\t\t};
\t\t\tname = Profile;
\t\t};
''';

const cleanPodfile = "platform :osx, '14.0'\n";

Directory makeTree({required String pbxproj, required String podfile}) {
  final dir = Directory.systemTemp.createTempSync('fah_min_platform_gate');
  addTearDown(() => dir.deleteSync(recursive: true));
  File(
    '${dir.path}/flutter_app/macos/Runner.xcodeproj/project.pbxproj',
  ).createSync(recursive: true)
    ..writeAsStringSync(pbxproj);
  File('${dir.path}/flutter_app/macos/Podfile')
    ..createSync()
    ..writeAsStringSync(podfile);
  // The vendored plugin's SwiftPM manifest is the opt-in signal; the pods
  // lane keeps it deleted (gh-1798 AC1).
  Directory(
    '${dir.path}/vendor/flutter_inappwebview_macos/macos/flutter_inappwebview_macos',
  ).createSync(recursive: true);
  return dir;
}

void addSpmState(
  Directory tree, {
  String? generatedFloor,
  List<String> pluginFloors = const [],
  bool markerInPbxproj = true,
}) {
  if (markerInPbxproj) {
    final pbx = File(
      '${tree.path}/flutter_app/macos/Runner.xcodeproj/project.pbxproj',
    );
    pbx.writeAsStringSync(
      '${pbx.readAsStringSync()}\t\t\tproductName = '
      'FlutterGeneratedPluginSwiftPackage;\n',
    );
  }
  final pkgs =
      '${tree.path}/flutter_app/macos/Flutter/ephemeral/Packages';
  if (generatedFloor != null) {
    File(
      '$pkgs/FlutterGeneratedPluginSwiftPackage/Package.swift',
    ).createSync(recursive: true)
      ..writeAsStringSync(
        'let package = Package(\n  platforms: [.macOS("$generatedFloor")],\n)\n',
      );
  }
  for (var i = 0; i < pluginFloors.length; i++) {
    File('$pkgs/.packages/plugin_$i/Package.swift').createSync(recursive: true)
      ..writeAsStringSync(
        'let package = Package(\n  platforms: [.macOS("${pluginFloors[i]}")],\n)\n',
      );
  }
}

ProcessResult runGate(Directory tree, {String min = appMin}) {
  return Process.runSync(
    'bash',
    [scriptPath, min, tree.path],
    workingDirectory: tree.path,
  );
}

void main() {
  test('gate script exists and is executable', () {
    final script = File(scriptPath);
    expect(script.existsSync(), isTrue, reason: '$scriptPath must exist');
    // Executable bit: the workflow invokes it directly from the build step.
    final mode = FileStat.statSync(scriptPath).mode;
    expect(mode & 0o111, isNot(0), reason: '$scriptPath must be +x');
    final content = script.readAsStringSync();
    expect(content.startsWith('#!'), isTrue, reason: 'shebang required');
  });

  test('AC1 — clean pods-lane tree passes', () {
    final tree = makeTree(
      pbxproj: pbxprojWith('14.0;'),
      podfile: cleanPodfile,
    );
    final r = runGate(tree);
    expect(r.exitCode, 0, reason: 'stdout: ${r.stdout}\nstderr: ${r.stderr}');
    expect(r.stdout, contains('OK'));
  });

  test('AC2a — FlutterGeneratedPluginSwiftPackage in pbxproj fails loud '
      'with the lane remediation', () {
    final tree = makeTree(
      pbxproj: pbxprojWith('14.0;'),
      podfile: cleanPodfile,
    );
    addSpmState(tree); // marker only — floors would all be fine
    final r = runGate(tree);
    expect(r.exitCode, 1, reason: 'SPM re-entry must fail the gate');
    final out = '${r.stdout}${r.stderr}';
    expect(out, contains('FLUTTER_SWIFT_PACKAGE_MANAGER'));
    expect(out, contains('Podfile.lock'));
  });

  test('AC2b — a plugin that regained Package.swift fails loud', () {
    final tree = makeTree(
      pbxproj: pbxprojWith('14.0;'),
      podfile: cleanPodfile,
    );
    // Package.swift mere presence is the SwiftPM opt-in signal (gh-1798).
    File(
      '${tree.path}/vendor/flutter_inappwebview_macos/macos/'
      'flutter_inappwebview_macos/Package.swift',
    ).createSync()
      ..writeAsStringSync('// .macOS("14.0")\n');
    final r = runGate(tree);
    expect(r.exitCode, 1);
    final out = '${r.stdout}${r.stderr}';
    expect(out, contains('Package.swift'));
    expect(out, contains('pods'));
  });

  test('AC3 — the literal gh-180 shape (generated 12.0 + product 14.0) '
      'fails with the floor message', () {
    final tree = makeTree(
      pbxproj: pbxprojWith('14.0;'),
      podfile: cleanPodfile,
    );
    addSpmState(
      tree,
      generatedFloor: '12.0',
      pluginFloors: ['14.0'],
    );
    final r = runGate(tree);
    expect(r.exitCode, 1);
    final out = '${r.stdout}${r.stderr}';
    expect(out, contains('14.0'));
    expect(out, contains('12.0'));
    expect(out, contains('minimum platform version'));
  });

  test('AC4 — floor scan catches a violation in a LATER manifest '
      '(multi-item)', () {
    final tree = makeTree(
      pbxproj: pbxprojWith('14.0;'),
      podfile: cleanPodfile,
    );
    addSpmState(
      tree,
      generatedFloor: '14.0',
      // first two fine, violation third — a single-item scan would pass
      pluginFloors: ['10.15', '12.3', '15.0'],
    );
    final r = runGate(tree);
    expect(r.exitCode, 1);
    expect('${r.stdout}${r.stderr}', contains('15.0'));
  });

  test('AC4b — generated floor below app floor with all products under it '
      'is reported but not fatal (no false red)', () {
    final tree = makeTree(
      pbxproj: pbxprojWith('14.0;'),
      podfile: cleanPodfile,
    );
    addSpmState(
      tree,
      generatedFloor: '12.0',
      pluginFloors: ['10.15', '11.0'],
    );
    final r = runGate(tree);
    expect(r.exitCode, 0, reason: 'products ≤ floor builds fine; warn only');
    final out = '${r.stdout}${r.stderr}';
    expect(out, contains('12.0'));
  });

  test('AC5a — MACOSX_DEPLOYMENT_TARGET drift below the app floor fails',
      () {
    final tree = makeTree(
      pbxproj: pbxprojWith('13.0;'),
      podfile: cleanPodfile,
    );
    expect(runGate(tree).exitCode, 1);
  });

  test('AC5b — Podfile platform drift fails', () {
    final tree = makeTree(
      pbxproj: pbxprojWith('14.0;'),
      podfile: "platform :osx, '10.15'\n",
    );
    final r = runGate(tree);
    expect(r.exitCode, 1);
    expect('${r.stdout}${r.stderr}', contains('Podfile'));
  });

  test('AC6 — missing pbxproj fails gracefully', () {
    final tree = makeTree(pbxproj: '', podfile: cleanPodfile);
    File(
      '${tree.path}/flutter_app/macos/Runner.xcodeproj/project.pbxproj',
    ).deleteSync();
    final r = runGate(tree);
    expect(r.exitCode, 1);
    expect('${r.stdout}${r.stderr}', contains('project.pbxproj'));
  });

  test('AC6b — missing Podfile fails gracefully', () {
    final tree = makeTree(pbxproj: pbxprojWith('14.0;'), podfile: '');
    File('${tree.path}/flutter_app/macos/Podfile').deleteSync();
    final r = runGate(tree);
    expect(r.exitCode, 1);
    expect('${r.stdout}${r.stderr}', contains('Podfile'));
  });

  test('the committed tree passes the gate (real repo state)', () {
    // The gate's default repo-root resolution: run it with no root arg from
    // the repo root — the state this task ships must be green by default.
    final r = Process.runSync('bash', [scriptPath, appMin]);
    expect(
      r.exitCode,
      0,
      reason: 'stdout: ${r.stdout}\nstderr: ${r.stderr}',
    );
  });
}

// gh-180 — lane guard for the macOS desktop DMG legs. The legs went red
// (v1.0.630, build-macos run 39905803673, 2026-10-23) when the tool's
// best-effort FlutterGeneratedPluginSwiftPackage floor bump skipped on the
// first Xcode 27 run while a 14.0-floored SwiftPM product still existed.
// The gh-180 fix moves BOTH matrix arch legs to the pure CocoaPods lane
// (every macOS plugin is already pinned in flutter_app/macos/Podfile.lock)
// and adds a build-time REG gate so a lane or floor drift fails in seconds
// with the remediation instead of Xcode's cryptic
// "requires minimum platform version" error after a 50+-minute pass.
//
// Static workflow-shape assert (the "workflow-shape test never-again"
// pattern of ci_macos_signing_window_guard_test.dart /
// workflow_selfhosted_legs_test.dart):
//
//   AC1  the build-macos job pins FLUTER_SWIFT_PACKAGE_MANAGER=0 — the
//        feature env override is read per flutter invocation
//        (flutter_features_config.dart), the SPM migration then skips
//        cleanly, and the Podfile platform (:osx, '14.0') — not a silent
//        tool bump — is the authority for the effective pod floors;
//   AC2  the Build macOS release step runs `flutter build macos
//        --config-only` + scripts/assert_macos_min_platform.sh BEFORE the
//        real `flutter build macos --release` — the gate must see the
//        post-config state and fail before any compile minute is spent;
//   AC3  the no-sandbox flavor rides the same job env, so it is covered
//        by the same lane pin (no separate assertion needed — asserted
//        here anyway as a doc pin that the step invokes plain flutter).
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

const workflowPath = '.github/workflows/build-macos.yml';
const jobName = 'build-macos';
const buildStepPrefix = 'Build macOS release (';

String read(String path) => File(path).readAsStringSync();

YamlMap jobsOf(String workflowPath) =>
    loadYaml(read(workflowPath))['jobs'] as YamlMap;

/// The `run` script of the named step in the named job of the workflow.
String stepScriptOf(String workflowPath, String job, String stepName) {
  final steps = (jobsOf(workflowPath)[job] as YamlMap)['steps'] as YamlList;
  return steps
      .whereType<YamlMap>()
      .firstWhere((s) => (s['name']?.toString() ?? '') == stepName)['run']
      .toString();
}

void main() {
  test('AC1 — build-macos job pins FLUTER_SWIFT_PACKAGE_MANAGER=0 (gh-180)',
      () {
    final job = jobsOf(workflowPath)[jobName] as YamlMap;
    final env = job['env'] as YamlMap?;
    expect(env, isNotNull, reason: 'the build-macos job must carry an env block');
    final pin = env?['FLUTTER_SWIFT_PACKAGE_MANAGER']?.toString();
    expect(
      pin,
      '0',
      reason:
          'Flutter 3.47 stable ships the SwiftPM feature enabled-by-default; '
          'without the pin every fresh-clone build re-enters the '
          'FlutterGeneratedPluginSwiftPackage lane whose 12.0 floor bump '
          'depends on a silent xcodebuild -showBuildSettings read — the '
          'exact mechanism that red run 39905803673 (gh-180) when a '
          '14.0-floored product existed. The pods lane (Podfile.lock) '
          'builds every macOS plugin at the Podfile platform instead.',
    );
  });

  test('AC2 — Build macOS release step: config-only + min-platform gate '
      'before the release build', () {
    final steps = (jobsOf(workflowPath)[jobName] as YamlMap)['steps']
        as YamlList;
    final buildStep = steps.whereType<YamlMap>().firstWhere(
          (s) => (s['name']?.toString() ?? '').startsWith(buildStepPrefix),
        );
    final script = buildStep['run'].toString();

    expect(
      script,
      contains('flutter build macos --config-only'),
      reason:
          'the gate must run against the state a REAL tool pass produced — '
          'config-only drives the SPM migration (or its clean skip) and pod '
          'install without compiling',
    );
    expect(
      script,
      contains('scripts/assert_macos_min_platform.sh'),
      reason: 'the gh-180 REG gate must be invoked from the build step',
    );

    final gateIdx = script.indexOf('scripts/assert_macos_min_platform.sh');
    final releaseIdx = script.indexOf('flutter build macos --release');
    expect(releaseIdx, greaterThan(-1));
    expect(
      gateIdx,
      lessThan(releaseIdx),
      reason:
          'fail loud at build time, not at release time: the gate must '
          'reject a drifted lane/floor BEFORE the long release build starts',
    );
  });

  test('AC3 — the committed pbxproj keeps the Runner-target floor shape the '
      'gate asserts (3×14.0, nothing else)', () {
    final pbxproj = read('flutter_app/macos/Runner.xcodeproj/project.pbxproj');
    final entries =
        RegExp(r'MACOSX_DEPLOYMENT_TARGET = ([^;]+);').allMatches(pbxproj);
    expect(entries, isNotEmpty);
    for (final m in entries) {
      expect(
        m.group(1),
        '14.0',
        reason:
            'every MACOSX_DEPLOYMENT_TARGET in the macOS Runner project '
            'must equal the app minimum (14.0) — the Runner target pins it '
            'per-config; a second, lower value is a silent '
            'deployment-target regression the gate would reject on the '
            'runner (gh-180 AC: every SPM/pods target ≥ 14.0)',
      );
    }
    // The Runner target must pin all three configs explicitly — the
    // aggregate/tests targets inherit Xcode defaults and are not allowed
    // to consume package products (the pods lane keeps the pbxproj free
    // of FlutterGeneratedPluginSwiftPackage).
    expect(
      RegExp(r'MACOSX_DEPLOYMENT_TARGET = 14\.0;').allMatches(pbxproj).length,
      3,
      reason: 'Runner Debug/Release/Profile — the gh-1798-era shape',
    );
    expect(
      pbxproj.contains('FlutterGeneratedPluginSwiftPackage'),
      isFalse,
      reason:
          'the committed project must stay free of SwiftPM integration — '
          'the tool adds it only when the feature is enabled, and the '
          'build-macos job pins the feature off (gh-180)',
    );
  });
}

